            <BdsButton style={{ marginRight: '8px' }} onClick={handlePreviousStep}>
              Previous step
            </BdsButton>
          )}
          {(step == 0 || step == 1) && <BdsButton onClick={handleNextStep}>Next step</BdsButton>}
          {step == 2 && <BdsButton onClick={handleNextStep}>Finish</BdsButton>}
        </div>
      </div>
    </>
  );
};

